<template><el-main><h2>健康商城业务记录</h2><el-alert title="订单和支付记录保持只读；本地演示结算以LOCAL_DEMO标识" type="info" :closable="false"/><el-tabs v-model="tab" @tab-change="load"><el-tab-pane label="秒杀商品" name="secgoods"/><el-tab-pane label="订单记录" name="secorder"/><el-tab-pane label="支付记录" name="secpay"/></el-tabs><el-button @click="load">刷新</el-button><el-table :data="rows" stripe><el-table-column v-for="k in keys" :key="k" :prop="k" :label="labels[k]||k" min-width="140" show-overflow-tooltip/></el-table></el-main></template><script setup>import{ref,computed,onMounted}from'vue';import{call}from'@/api/health';const tab=ref('secgoods'),rows=ref([]),keys=computed(()=>rows.value.length?Object.keys(rows.value[0]):[]),labels={id:'编号',title:'商品名称',price:'价格',stock:'库存',startTime:'活动开始',endTime:'活动结束',userId:'用户编号',goodsId:'商品编号',amount:'金额',status:'状态',createdAt:'创建时间',expiresAt:'到期时间',paidAt:'结算时间',userName:'用户名称',userPhone:'电话',orderId:'订单号',tradeNo:'交易号',provider:'支付来源',imageUrl:'图片地址'};async function load(){rows.value=(await call(tab.value+'/list')).data}onMounted(load)</script>